// Generated by OpenFlex Neo - Async/Await Demo (Simplified)
// AS4 -> JavaScript

// Polyfill for Node.js
const trace = typeof console !== 'undefined' ? console.log : () => {};

trace("=== Async/Await Demo ===");
trace("");

// Simulate async operations
function delay(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

function fetchUser(id) {
    return new Promise((resolve) => {
        setTimeout(() => {
            resolve({ id, name: `User${id}`, email: `user${id}@example.com` });
        }, 100);
    });
}

function fetchPosts(userId) {
    return new Promise((resolve) => {
        setTimeout(() => {
            resolve([
                { id: 1, title: "Post 1", userId },
                { id: 2, title: "Post 2", userId }
            ]);
        }, 100);
    });
}

// Async function examples
async function getUserData(userId) {
    trace("Fetching user...");
    const user = await fetchUser(userId);
    trace("User fetched:", user.name);

    trace("Fetching posts...");
    const posts = await fetchPosts(user.id);
    trace("Posts fetched:", posts.length, "posts");

    return { user, posts };
}

async function runParallel() {
    trace("\n--- Parallel Execution ---");
    const [user1, user2, user3] = await Promise.all([
        fetchUser(1),
        fetchUser(2),
        fetchUser(3)
    ]);
    trace("Fetched 3 users in parallel:", user1.name, user2.name, user3.name);
}

async function handleError() {
    trace("\n--- Error Handling ---");
    try {
        await delay(50);
        throw new Error("Something went wrong!");
    } catch (error) {
        trace("Caught error:", error.message);
    }
}

// Run demos
(async () => {
    trace("--- Sequential Execution ---");
    await getUserData(1);
    await runParallel();
    await handleError();
    trace("\n✅ All async operations complete!");
})();
